<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
ent_variant_install();
$pageTitle='Varyant Sistemi';$currentPage='variants';$pdo=ent_db();$error='';$notice=trim((string)($_GET['notice']??''));
try{
 if($_SERVER['REQUEST_METHOD']==='POST'){
  ent_verify_csrf();$action=(string)($_POST['action']??'');
  if($action==='save_group'){
   $id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$desc=trim((string)($_POST['description']??''));
   $type=(string)($_POST['selection_type']??'single');$type=in_array($type,['single','multiple'],true)?$type:'single';
   $required=isset($_POST['is_required'])?1:0;$min=max(0,(int)($_POST['min_select']??0));$max=max(1,(int)($_POST['max_select']??1));
   if($type==='single'){$max=1;$min=$required?1:0;}elseif($max<$min){$max=$min;}
   if($name==='')throw new RuntimeException('Grup adı zorunludur.');
   if($id>0){$pdo->prepare('UPDATE variant_groups SET name=?,description=?,selection_type=?,is_required=?,min_select=?,max_select=?,updated_at=? WHERE id=?')->execute([$name,$desc,$type,$required,$min,$max,date('Y-m-d H:i:s'),$id]);}
   else{$sort=(int)$pdo->query('SELECT COALESCE(MAX(sort_order),0)+10 FROM variant_groups')->fetchColumn();$pdo->prepare('INSERT INTO variant_groups(name,description,selection_type,is_required,min_select,max_select,sort_order,is_active,created_at) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$name,$desc,$type,$required,$min,$max,$sort,1,date('Y-m-d H:i:s')]);}
   ent_redirect('variants.php?notice='.rawurlencode('Varyant grubu kaydedildi.'));
  }
  if($action==='save_option'){
   $id=(int)($_POST['id']??0);$gid=(int)($_POST['group_id']??0);$name=trim((string)($_POST['name']??''));$delta=(float)str_replace(',','.',(string)($_POST['price_delta']??'0'));$default=isset($_POST['is_default'])?1:0;
   if($gid<1||$name==='')throw new RuntimeException('Grup ve seçenek adı zorunludur.');
   $pdo->beginTransaction();
   if($default){$pdo->prepare('UPDATE variant_options SET is_default=0 WHERE group_id=?')->execute([$gid]);}
   if($id>0){$pdo->prepare('UPDATE variant_options SET name=?,price_delta=?,is_default=?,updated_at=? WHERE id=? AND group_id=?')->execute([$name,$delta,$default,date('Y-m-d H:i:s'),$id,$gid]);}
   else{$sortStmt=$pdo->prepare('SELECT COALESCE(MAX(sort_order),0)+10 FROM variant_options WHERE group_id=?');$sortStmt->execute([$gid]);$pdo->prepare('INSERT INTO variant_options(group_id,name,price_delta,sort_order,is_default,is_active,created_at) VALUES(?,?,?,?,?,?,?)')->execute([$gid,$name,$delta,(int)$sortStmt->fetchColumn(),$default,1,date('Y-m-d H:i:s')]);}
   $pdo->commit();ent_redirect('variants.php?group='.$gid.'&notice='.rawurlencode('Seçenek kaydedildi.'));
  }
  if($action==='assign_products'){
   $gid=(int)($_POST['group_id']??0);$ids=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['product_ids']??[])))));if($gid<1)throw new RuntimeException('Grup bulunamadı.');
   $pdo->beginTransaction();$pdo->prepare('DELETE FROM product_variant_groups WHERE group_id=?')->execute([$gid]);$ins=$pdo->prepare('INSERT INTO product_variant_groups(product_id,group_id,sort_order,created_at) VALUES(?,?,?,?)');foreach($ids as $i=>$pid)$ins->execute([$pid,$gid,($i+1)*10,date('Y-m-d H:i:s')]);$pdo->commit();
   ent_redirect('variants.php?group='.$gid.'&notice='.rawurlencode('Ürün atamaları güncellendi.'));
  }
  if($action==='toggle_group'){$pdo->prepare('UPDATE variant_groups SET is_active=1-is_active,updated_at=? WHERE id=?')->execute([date('Y-m-d H:i:s'),(int)($_POST['id']??0)]);ent_redirect('variants.php');}
  if($action==='delete_option'){$gid=(int)($_POST['group_id']??0);$pdo->prepare('DELETE FROM variant_options WHERE id=? AND group_id=?')->execute([(int)($_POST['id']??0),$gid]);ent_redirect('variants.php?group='.$gid);}
 }
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
$groups=$pdo->query("SELECT g.*,(SELECT COUNT(*) FROM variant_options o WHERE o.group_id=g.id) option_count,(SELECT COUNT(*) FROM product_variant_groups pvg WHERE pvg.group_id=g.id) product_count FROM variant_groups g ORDER BY g.sort_order,g.id")->fetchAll(PDO::FETCH_ASSOC);
$selectedId=(int)($_GET['group']??($groups[0]['id']??0));$selected=null;foreach($groups as $g)if((int)$g['id']===$selectedId)$selected=$g;
$options=[];$assigned=[];if($selected){$st=$pdo->prepare('SELECT * FROM variant_options WHERE group_id=? ORDER BY sort_order,id');$st->execute([$selectedId]);$options=$st->fetchAll(PDO::FETCH_ASSOC);$st=$pdo->prepare('SELECT product_id FROM product_variant_groups WHERE group_id=?');$st->execute([$selectedId]);$assigned=array_map('intval',$st->fetchAll(PDO::FETCH_COLUMN));}
$products=$pdo->query('SELECT p.id,p.name,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY c.sort_order,c.name,p.sort_order,p.name')->fetchAll(PDO::FETCH_ASSOC);
require __DIR__.'/_header.php';
?>

<?php if($notice):?><div class="ch-flash ch-flash--success"><?=ent_e($notice)?></div><?php endif;?><?php if($error):?><div class="ch-flash ch-flash--danger"><?=ent_e($error)?></div><?php endif;?>
<section class="mw-page"><header class="mw-page-head"><div><span class="ch-eyebrow">MENÜ YÖNETİMİ</span><h2>Varyantlar</h2><p>Boyut, ekstra ve seçim gruplarını kart tabanlı çalışma alanında yönetin.</p></div><a class="ch-btn ch-btn--primary" href="variants.php?action=create">＋ Yeni Varyant Grubu</a></header><nav class="ch-workspace-tabs"><a href="menu.php">Genel Bakış</a><a href="products.php">Ürünler</a><a href="categories.php">Kategoriler</a><a class="active" href="variants.php">Varyantlar</a><a href="media.php">Medya Merkezi</a></nav><div class="mw-variant-layout"><aside class="ch-card mw-group-column"><header class="ch-section-head"><div><span class="ch-eyebrow">GRUPLAR</span><h3><?=count($groups)?> varyant grubu</h3></div></header><div class="mw-group-list"><?php foreach($groups as $g):?><a class="mw-group-item <?=$selectedId===(int)$g['id']?'active':''?>" href="variants.php?group=<?=(int)$g['id']?>"><div><b><?=ent_e($g['name'])?></b><small><?=ent_e($g['selection_type']==='single'?'Tek seçim':'Çoklu seçim')?> · <?=(int)$g['option_count']?> seçenek</small></div><span><?=(int)$g['product_count']?> ürün</span></a><?php endforeach;?><?php if(!$groups):?><div class="ch-empty"><b>Varyant grubu yok.</b></div><?php endif;?></div></aside><section class="mw-variant-main"><?php if($selected):?><article class="ch-card mw-variant-summary"><header><div><span class="ch-eyebrow">SEÇİLİ GRUP</span><h3><?=ent_e($selected['name'])?></h3><p><?=ent_e((string)($selected['description']?:'Açıklama eklenmemiş.'))?></p></div><div><span class="ch-badge <?=$selected['is_active']?'ch-badge--success':'ch-badge--muted'?>"><?=$selected['is_active']?'Aktif':'Pasif'?></span><a class="ch-btn ch-btn--ghost" href="variants.php?group=<?=$selectedId?>&edit_group=1">Düzenle</a></div></header><div class="mw-mini-stats"><div><b><?=count($options)?></b><span>Seçenek</span></div><div><b><?=count($assigned)?></b><span>Bağlı ürün</span></div><div><b><?=ent_e($selected['selection_type']==='single'?'Tek':'Çoklu')?></b><span>Seçim tipi</span></div></div></article><div class="mw-variant-panels"><article class="ch-card"><header class="ch-section-head"><div><span class="ch-eyebrow">SEÇENEKLER</span><h3>Grup seçenekleri</h3></div></header><form method="post" class="mw-inline-form"><input type="hidden" name="csrf_token" value="<?=ent_e($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="save_option"><input type="hidden" name="group_id" value="<?=$selectedId?>"><input name="name" required placeholder="Seçenek adı"><input name="price_delta" inputmode="decimal" value="0" placeholder="Fiyat farkı"><label><input type="checkbox" name="is_default"> Varsayılan</label><button class="ch-btn ch-btn--primary">Ekle</button></form><div class="mw-option-list"><?php foreach($options as $o):?><div><span class="mw-drag">⋮⋮</span><div><b><?=ent_e($o['name'])?></b><small><?=((float)$o['price_delta']>=0?'+':'').number_format((float)$o['price_delta'],2,',','.')?> ₺ <?=$o['is_default']?'· Varsayılan':''?></small></div><form method="post"><input type="hidden" name="csrf_token" value="<?=ent_e($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="delete_option"><input type="hidden" name="group_id" value="<?=$selectedId?>"><input type="hidden" name="id" value="<?=(int)$o['id']?>"><button class="ch-icon-action ch-icon-action--danger">×</button></form></div><?php endforeach;?><?php if(!$options):?><div class="ch-empty"><small>Henüz seçenek eklenmemiş.</small></div><?php endif;?></div></article><article class="ch-card"><header class="ch-section-head"><div><span class="ch-eyebrow">ÜRÜNLERE ATA</span><h3><?=count($assigned)?> ürün seçili</h3></div></header><form method="post"><input type="hidden" name="csrf_token" value="<?=ent_e($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="assign_products"><input type="hidden" name="group_id" value="<?=$selectedId?>"><label class="mw-search"><span>⌕</span><input class="product-search" type="search" placeholder="Ürün ara…" data-product-filter></label><div class="mw-product-checks" data-product-checks><?php foreach($products as $p):?><label data-search="<?=ent_e(mb_strtolower($p['name'].' '.$p['category_name'],'UTF-8'))?>"><input type="checkbox" name="product_ids[]" value="<?=(int)$p['id']?>" <?=in_array((int)$p['id'],$assigned,true)?'checked':''?>><span><b><?=ent_e($p['name'])?></b><small><?=ent_e($p['category_name'])?></small></span></label><?php endforeach;?></div><button class="ch-btn ch-btn--primary ch-btn--full">Atamaları Kaydet</button></form></article></div><?php else:?><div class="ch-empty ch-card"><b>Bir varyant grubu seçin veya yeni grup oluşturun.</b></div><?php endif;?></section></div></section>
<?php $groupDrawer=(($_GET['action']??'')==='create')||isset($_GET['edit_group']);if($groupDrawer):?><div class="mw-drawer-backdrop"><aside class="mw-drawer mw-drawer--small"><header><div><span class="ch-eyebrow"><?=$selected?'GRUBU DÜZENLE':'YENİ GRUP'?></span><h3><?=$selected?ent_e($selected['name']):'Varyant grubu oluştur'?></h3></div><a class="ch-icon-action" href="variants.php<?=$selected?'?group='.$selectedId:''?>">×</a></header><form method="post" class="mw-editor"><input type="hidden" name="csrf_token" value="<?=ent_e($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="save_group"><input type="hidden" name="id" value="<?=$selected?$selectedId:0?>"><section class="mw-editor-panel active"><div class="mw-field-grid"><label class="span-2">Grup adı<input name="name" required value="<?=ent_e($selected['name']??'')?>" placeholder="Örn. Boyut"></label><label class="span-2">Açıklama<textarea name="description" rows="3"><?=ent_e($selected['description']??'')?></textarea></label><label>Seçim tipi<select name="selection_type"><option value="single" <?=($selected['selection_type']??'single')==='single'?'selected':''?>>Tek seçim</option><option value="multiple" <?=($selected['selection_type']??'')==='multiple'?'selected':''?>>Çoklu seçim</option></select></label><label>En fazla seçim<input type="number" min="1" name="max_select" value="<?=(int)($selected['max_select']??1)?>"></label></div><label class="mw-switch"><input type="checkbox" name="is_required" value="1" <?=!empty($selected['is_required'])?'checked':''?>><span><b>Seçim zorunlu</b><small>Müşteri veya personel seçim yapmadan devam edemez</small></span></label></section><footer><a class="ch-btn ch-btn--ghost" href="variants.php">Vazgeç</a><button class="ch-btn ch-btn--primary">Kaydet</button></footer></form></aside></div><?php endif;?>
<?php require __DIR__.'/_footer.php';?>
